1	import { describe, it, expect } from "vitest";
2	import { execFile } from "node:child_process";
3	
4	interface CliRun {
5	  stdout: string;
6	  stderr: string;
7	  code: number;
8	}
9	
10	/**
11	 * Runs the CLI as a real subprocess. Exit codes and the separation of stdout
12	 * from stderr are the contract the spec states, and neither survives being
13	 * tested through a function call.
14	 */
15	const runCli = (input: string): Promise<CliRun> =>
16	  new Promise((resolve) => {
17	    const child = execFile("npx", ["tsx", "src/cli.ts"], (error, stdout, stderr) => {
18	      resolve({ stdout, stderr, code: error && "code" in error ? Number(error.code) : 0 });
19	    });
20	
21	    child.stdin?.end(input);
22	  });
23	
24	describe("claim-office CLI", () => {
25	  it("writes the results JSON to stdout for a valid scenario", async () => {
26	    const scenario = {
27	      customer: { yearsWithMHPCO: 5 },
28	      steps: [
29	        {
30	          op: "quote",
31	          items: [{ type: "amulet", material: "silver", enchantment: 2, cursed: false }],
32	        },
33	        {
34	          op: "claim",
35	          policy: 0,
36	          incident: { cause: "fire", damages: [{ itemType: "amulet", amount: 200 }] },
37	        },
38	      ],
39	    };
40	
41	    const { stdout, code } = await runCli(JSON.stringify(scenario));
42	
43	    // 60 base − 12 loyalty + 6 first insurance + 5 fee = 59.
44	    // Damage 200 − 100 deductible = 100; cap 1200 leaves 1100.
45	    expect(code).toBe(0);
46	    expect(JSON.parse(stdout)).toEqual({
47	      results: [{ premium: 59 }, { payout: 100, remainingCap: 1100 }],
48	    });
