/** The modifier amount `rate` contributes against `subunits` — not the total. */
const rateAmount = (subunits: number, rate: Rate): number => partOf(subunits, rate);

/** Premiums round up — in the MHPCO's favour. */

/** The part of `subunits` that `fraction` denotes. */
const partOf = (subunits: number, fraction: Fraction): number =>
  (subunits * fraction.num) / fraction.den;

/** The part of `subunits` that `share` reimburses. */
const shareAmount = (subunits: number, share: Share): number => partOf(subunits, share);

const FULL_REIMBURSEMENT: Share = { num: 100, den: 100 };
